// HeyReach fires one webhook per event type, all pointed at this same URL.
// n8n Webhook v2 puts the JSON POST body under .body — fall back to root just in case.
const root = $input.item.json;
const p = root.body !== undefined ? root.body : root;

// CONFIRMED real HeyReach payload shape (verified from live test payload 2026-08-01):
// event_type, campaign{name,id}, sender{first_name,last_name,full_name,email_address,profile_url},
// lead{id,profile_url,first_name,last_name,full_name,company_name,position,email_address,enriched_email,custom_email},
// recent_messages[]{creation_time, message, is_reply, message_type}
const lead = p.lead || p.prospect || {};
const campaign = p.campaign || {};
const sender = p.sender || {};

const eventType = String(p.event_type || p.eventType || p.event || p.type || 'unknown').toLowerCase();

// --- Identity fields (used for matching + creation) ---
let linkedInUrl = lead.profile_url || lead.profileUrl || lead.linkedInProfileUrl
  || lead.linkedin_url || lead.linkedInUrl || '';
linkedInUrl = String(linkedInUrl).trim().replace(/\/$/, '');

const email = String(lead.email_address || lead.enriched_email || lead.custom_email || lead.email || '').trim().toLowerCase();
const firstName = String(lead.first_name || lead.firstName || '').trim();
let lastName = String(lead.last_name || lead.lastName || '').trim();
if (!lastName) lastName = firstName || 'LinkedIn Lead'; // Salesforce Lead requires LastName
const company = String(lead.company_name || lead.companyName || lead.organizationName || '').trim()
  || 'Unknown (from LinkedIn)'; // Salesforce Lead requires Company
const title = String(lead.position || lead.headline || lead.title || '').trim();
const campaignName = String(campaign.name || p.campaignName || '').trim();

// --- Message text: HeyReach sends an array of recent messages, not a single field.
// Attachments/voice notes have an empty "message" string and a "message_type" instead.
// Grab the most recent item with real text; fall back to noting the attachment type.
const messages = Array.isArray(p.recent_messages) ? p.recent_messages : [];
let messageText = '';
for (let i = messages.length - 1; i >= 0; i--) {
  const m = messages[i] || {};
  if (m.message && String(m.message).trim()) {
    messageText = String(m.message).trim();
    break;
  }
}
if (!messageText) {
  const lastNonText = messages.slice().reverse().find(m => m && m.message_type);
  if (lastNonText) messageText = `[${lastNonText.message_type} - no text content]`;
}

// Full transcript of everything in this batch (useful when several messages arrive together)
const transcript = messages.map(m => {
  const who = m.is_reply ? 'Lead' : 'You';
  const text = (m.message && String(m.message).trim())
    ? String(m.message).trim()
    : (m.message_type ? `[${m.message_type}]` : '');
  return `${who}: ${text}`;
}).join('\n');

// --- Human-readable label per event type (real HeyReach values are lower_snake_case) ---
const labels = {
  connection_request_sent: 'Connection request sent',
  connection_request_accepted: 'Connection request accepted',
  message_sent: 'Message sent',
  every_message_reply_received: 'Reply received',
  inmail_sent: 'InMail sent',
  inmail_reply_received: 'InMail reply received',
  follow_sent: 'Follow sent',
  liked_post: 'Liked a post',
  viewed_profile: 'Viewed profile',
  lead_tag_updated: 'Lead tag updated',
  campaign_completed: 'Campaign completed'
};
const label = labels[eventType] || eventType;

// --- Salesforce Task fields ---
const subject = `HeyReach: ${label}${campaignName ? ' - ' + campaignName : ''}`;
const descriptionParts = [
  `Event: ${label}`,
  campaignName ? `Campaign: ${campaignName}` : null,
  linkedInUrl ? `LinkedIn: ${linkedInUrl}` : null,
  sender.full_name ? `Sender: ${sender.full_name}` : null,
  transcript ? `Message(s):\n${transcript}` : null
].filter(Boolean);
const description = descriptionParts.join('\n');

// SOQL-safe versions (escape single quotes) for the lookup query
const esc = (s) => String(s).replace(/'/g, "\\'");

return {
  json: {
    eventType,
    label,
    linkedInUrl,
    email,
    firstName,
    lastName,
    company,
    title,
    campaignName,
    messageText,
    subject,
    description,
    activityDate: new Date().toISOString().slice(0, 10),
    soql_email: esc(email),
    soql_linkedInUrl: esc(linkedInUrl)
  }
};
